134	// SubscriptionFilter narrows Subscriptions.
135	type SubscriptionFilter struct {
136		CustomerID string
137		Status     SubStatus
138	}
139	
140	// Subscriptions returns an organization's subscriptions that match f, oldest first.
141	func (s *Store) Subscriptions(orgID string, f SubscriptionFilter) []Subscription {
142		s.mu.Lock()
143		defer s.mu.Unlock()
144		out := []Subscription{}
145		for _, sub := range s.subs {
146			if sub.OrgID != orgID || (f.CustomerID != "" && sub.CustomerID != f.CustomerID) || (f.Status != "" && sub.Status != f.Status) {
147				continue
148			}
149			out = append(out, copySub(sub))
150		}
151		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
152		return out
153	}
154	
155	// UpdateSubscription changes a subscription with f, which may refuse with an error.
156	func (s *Store) UpdateSubscription(orgID, id string, f func(*Subscription) error) (Subscription, error) {
157		s.mu.Lock()
158		defer s.mu.Unlock()
159		old, ok := s.subs[id]
160		if !ok || old.OrgID != orgID {
161			return Subscription{}, ErrNotFound
162		}
163		sub := copySub(old)
164		if err := f(&sub); err != nil {
165			return Subscription{}, err
166		}
167		sub.ID, sub.OrgID, sub.CustomerID, sub.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.CreatedAt
168		if sub.Quantity <= 0 {
169			return Subscription{}, invalid("the quantity must be at least 1")
170		}
171		if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != orgID {
172			return Subscription{}, ErrNotFound
173		}
174		s.subs[id] = sub
175		return copySub(sub), nil
176	}
