281	func (s *Store) Invoice(orgID, id string) (Invoice, bool) {
282		s.mu.Lock()
283		defer s.mu.Unlock()
284		inv, ok := s.invoices[id]
285		if !ok || inv.OrgID != orgID {
286			return Invoice{}, false
287		}
288		return copyInvoice(inv), true
289	}
