14	func TestCreateChargesTheFirstPeriod(t *testing.T) {
15		e := apitest.New(t)
16		ctx := context.Background()
17		c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
18		_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
19		p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
20		sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 3})
