90		sub, err := e.Subs.Cancel(ctx, e.Acme.ID, sub.ID, true)
91		if err != nil || sub.Status != store.Active || !sub.CancelAtPeriodEnd {
92			t.Fatalf("cancel = %+v, %v", sub, err)
