99		if got.Status != store.Canceled || got.CanceledAt == nil || !got.CanceledAt.Equal(sub.CurrentPeriodEnd) {
100			t.Fatalf("after the period = %+v", got)
101		}
102		if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
103			t.Fatalf("invoices = %d, want only the first", len(invs))
104		}
