107	func TestMeteredBillsUsageInArrears(t *testing.T) {
108		e := apitest.New(t)
109		ctx := context.Background()
110		c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
111		p, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "API calls", Currency: money.USD, UnitAmount: 2, Interval: store.Monthly, UsageType: store.Metered}, e.Clock.Now())
112		sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
113		if err != nil {
114			t.Fatal(err)
115		}
116		if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{}); len(invs) != 0 {
117			t.Fatalf("a metered plan was invoiced in advance: %+v", invs)
118		}
119		start, end := sub.CurrentPeriodStart, sub.CurrentPeriodEnd
120		for _, u := range []struct {
121			q  int64
122			at time.Time
123		}{{100, start}, {250, start.Add(48 * time.Hour)}, {7, end}} {
124			if _, err := e.Store.AddUsage(e.Acme.ID, sub.ID, u.q, u.at, e.Clock.Now()); err != nil {
125				t.Fatal(err)
126			}
127		}
128		e.Clock.Set(end)
129		if _, err := e.Subs.RenewDue(ctx); err != nil {
130			t.Fatal(err)
131		}
132		invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
133		if len(invs) != 1 || len(invs[0].Lines) != 1 || invs[0].Lines[0].Quantity != 350 || !invs[0].PeriodEnd.Equal(end) {
134			t.Fatalf("invoices = %+v (usage at the period's end belongs to the next period)", invs)
135		}
136	}
