// Prorate returns amount times num/den, rounded half away from zero to a whole minor unit. The product is computed without
// overflow, so a large amount times a long period is exact.
func Prorate(amount, num, den int64) int64 {
	n := new(big.Int).Mul(big.NewInt(amount), big.NewInt(num))
	d := big.NewInt(den)
	neg := (n.Sign() < 0) != (d.Sign() < 0)
	n.Abs(n)
	d.Abs(d)
	n.Add(n, new(big.Int).Rsh(d, 1))
	n.Quo(n, d)
	if neg {
		n.Neg(n)
	}
	return n.Int64()
}

