// UpdateInput changes a subscription; nil fields stay as they are.
type UpdateInput struct {
	PlanID   *string
	Quantity *int
}

// Update changes a subscription's plan or quantity. A subscription's value is its plan's unit amount times its quantity.
//
// An upgrade (a higher value) applies at once and is invoiced at once for the rest of the current period: the unused time on
// the old plan is credited and the remaining time on the new plan charged. A downgrade is pending: it takes effect at the next
// renewal. A change that keeps the value applies at once and bills nothing, and so does any change of a trialing
// subscription. Changing back to the current plan and quantity clears a pending change, as does an upgrade.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	old, ok := s.Store.Subscription(orgID, id)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	oldPlan, ok := s.Store.Plan(orgID, old.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	newPlan := oldPlan
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
		newPlan = p
	}
	qty := old.Quantity
	if in.Quantity != nil {
		qty = *in.Quantity
	}
	if qty <= 0 {
		return store.Subscription{}, fmt.Errorf("%w: the quantity must be at least 1", store.ErrInvalid)
	}
	if old.Status == store.Canceled {
		return store.Subscription{}, ErrCanceled
	}
	if oldPlan.Currency != newPlan.Currency || oldPlan.Interval != newPlan.Interval ||
		oldPlan.UsageType == store.Metered || newPlan.UsageType == store.Metered {
		return store.Subscription{}, ErrIncompatiblePlan
	}
	oldValue := oldPlan.UnitAmount * int64(old.Quantity)
	newValue := newPlan.UnitAmount * int64(qty)
	trialing := old.Status == store.Trialing
	downgrade := !trialing && newValue < oldValue
	upgrade := !trialing && newValue > oldValue
	same := newPlan.ID == old.PlanID && qty == old.Quantity

	sub, err := s.Store.UpdateSubscription(orgID, id, func(x *store.Subscription) error {
		if x.Status == store.Canceled {
			return ErrCanceled
		}
		if downgrade {
			pid, q := newPlan.ID, qty
			x.PendingPlanID, x.PendingQuantity = &pid, &q
			return nil
		}
		x.PlanID, x.Quantity = newPlan.ID, qty
		if upgrade || same {
			x.PendingPlanID, x.PendingQuantity = nil, nil
		}
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	if !upgrade {
		return sub, nil
	}
	return s.prorate(ctx, sub, oldPlan, newPlan, oldValue, newValue)
}

// prorate bills an upgrade: one invoice for the rest of the current period, crediting the unused time on the old plan and
// charging the remaining time on the new one. A declined charge makes the subscription past due.
func (s *Service) prorate(ctx context.Context, sub store.Subscription, oldPlan, newPlan store.Plan, oldValue, newValue int64) (store.Subscription, error) {
	now := s.Clock.Now()
	remaining := int64(sub.CurrentPeriodEnd.Sub(now) / time.Second)
	length := int64(sub.CurrentPeriodEnd.Sub(sub.CurrentPeriodStart) / time.Second)
	ps, pe := now, sub.CurrentPeriodEnd
	inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: newPlan.Currency,
		Lines: []store.Line{
			{Description: "Unused time on " + oldPlan.Name, Quantity: 1, UnitAmount: -money.Prorate(oldValue, remaining, length)},
			{Description: "Remaining time on " + newPlan.Name, Quantity: 1, UnitAmount: money.Prorate(newValue, remaining, length)},
		},
		DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, now)
	if err != nil {
		return sub, err
	}
	s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
	paid, err := s.charge(ctx, sub.OrgID, inv.ID)
	if err != nil {
		return sub, err
	}
	if !paid {
		return s.setStatus(ctx, sub, store.PastDue)
	}
	return sub, nil
}

