// charge pays an invoice from the customer's default payment method. It reports false when the charge was declined.
func (s *Service) charge(ctx context.Context, orgID, invoiceID string) (bool, error) {
	_, _, err := s.Payments.Pay(ctx, orgID, invoiceID, "")
	var decline *payments.DeclineError
	switch {
	case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
		return true, nil
	case errors.As(err, &decline):
		return false, nil
	default:
		return false, err
	}
}

	return s.charge(ctx, sub.OrgID, inv.ID)
}

