package subscriptions_test

import (
	"context"
	"errors"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/billing"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
)

// withPaymentMethod gives a customer a default payment method.
func withPaymentMethod(e *apitest.Env, c store.Customer, pm string) {
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = pm; return nil })
}

// The period of a subscription created on Jan 15 runs to Feb 15: 31 days, or 2678400 seconds. Ten days in, 21 days (1814400
// seconds) remain.
const tenDays = 10 * 24 * time.Hour

func TestUpgradeBillsTheRemainingTimeAtOnce(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	withPaymentMethod(e, c, "pm_card_visa")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Advance(tenDays)
	up, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID})
	if err != nil {
		t.Fatal(err)
	}
	if up.PlanID != pro.ID || up.Quantity != 1 || up.PendingPlanID != nil || up.PendingQuantity != nil ||
		!up.CurrentPeriodStart.Equal(sub.CurrentPeriodStart) || !up.CurrentPeriodEnd.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("upgrade = %+v", up)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 {
		t.Fatalf("invoices = %d, want the first period and the upgrade", len(invs))
	}
	// Unused: -round(2000 * 21/31) = -1355. Remaining: round(5000 * 21/31) = 3387.
	inv := invs[1]
	if inv.Status != store.InvoicePaid || len(inv.Lines) != 2 ||
		inv.Lines[0] != (store.Line{Description: "Unused time on Team", Quantity: 1, UnitAmount: -1355}) ||
		inv.Lines[1] != (store.Line{Description: "Remaining time on Pro", Quantity: 1, UnitAmount: 3387}) {
		t.Fatalf("upgrade invoice = %+v", inv)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 || cs[1].Amount != 2032 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestUpgradeInvoiceHasTheDiscountAndTheTax(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	if _, err := e.Store.UpdateOrg(e.Acme.ID, func(o *store.Org) error { o.TaxRateBP = 2000; return nil }); err != nil {
		t.Fatal(err)
	}
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	withPaymentMethod(e, c, "pm_card_visa")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1, DiscountPercent: 10})
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Advance(tenDays)
	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID}); err != nil {
		t.Fatal(err)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	inv := invs[len(invs)-1]
	// Lines -1355 and 3387: subtotal 2032, less 10% (203) is 1829, plus 20% tax (366) is 2195.
	if inv.DiscountPercent != 10 || inv.TaxRateBP != 2000 || billing.Compute(inv).Total != 2195 {
		t.Fatalf("upgrade invoice = %+v, totals %+v", inv, billing.Compute(inv))
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 || cs[1].Amount != 2195 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestUpgradeWithoutPaymentMethodStaysOpen(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Advance(tenDays)
	up, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID})
	if err != nil || up.Status != store.Active || up.PlanID != pro.ID {
		t.Fatalf("upgrade = %+v, %v", up, err)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 1 || invs[0].Status != store.InvoiceOpen || len(invs[0].Lines) != 2 {
		t.Fatalf("invoices = %+v", invs)
	}
}

func TestDeclinedUpgradeIsPastDue(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	withPaymentMethod(e, c, "pm_card_declined")
	e.Clock.Advance(tenDays)
	up, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID})
	if err != nil || up.Status != store.PastDue || up.PlanID != pro.ID {
		t.Fatalf("upgrade = %+v, %v", up, err)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[1].Status != store.InvoiceOpen {
		t.Fatalf("invoices = %+v", invs)
	}
}

func TestDowngradeIsPendingUntilRenewal(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	withPaymentMethod(e, c, "pm_card_visa")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: pro.ID, Quantity: 2})
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Advance(tenDays)
	down, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &team.ID, Quantity: new(int)})
	if err != nil {
		t.Fatal(err)
	}
	if down.PlanID != pro.ID || down.Quantity != 2 || down.PendingPlanID == nil || *down.PendingPlanID != team.ID ||
		down.PendingQuantity == nil || *down.PendingQuantity != 0 {
		t.Fatalf("downgrade = %+v", down)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("a downgrade was invoiced: %+v", invs)
	}

	e.Clock.Set(sub.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.PlanID != team.ID || got.Quantity != 0 || got.PendingPlanID != nil || got.PendingQuantity != nil {
		t.Fatalf("after the renewal = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || len(invs[1].Lines) != 1 || invs[1].Lines[0].UnitAmount != 2000 || invs[1].Lines[0].Quantity != 0 {
		t.Fatalf("renewal invoice = %+v", invs)
	}
}

func TestPendingDowngradeIsClearedByAnUpgradeOrByReturningToTheCurrentChange(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: pro.ID, Quantity: 2})
	if err != nil {
		t.Fatal(err)
	}
	one := 1
	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{Quantity: &one}); err != nil {
		t.Fatal(err)
	}
	two := 2
	back, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{Quantity: &two})
	if err != nil || back.PendingPlanID != nil || back.PendingQuantity != nil || back.Quantity != 2 {
		t.Fatalf("back to the current quantity = %+v, %v", back, err)
	}

	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{Quantity: &one}); err != nil {
		t.Fatal(err)
	}
	three := 3
	up, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{Quantity: &three})
	if err != nil || up.PendingPlanID != nil || up.PendingQuantity != nil || up.Quantity != 3 {
		t.Fatalf("upgrade = %+v, %v", up, err)
	}
}

func TestEqualValueChangeAppliesWithoutBilling(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	withPaymentMethod(e, c, "pm_card_visa")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	bulk := e.CreatePlan(e.Acme, "Bulk", "USD", "40.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 2})
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Advance(tenDays)
	same, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &bulk.ID, Quantity: new(int)})
	if err != nil {
		t.Fatal(err)
	}
	if same.PlanID != bulk.ID || same.Quantity != 0 || same.PendingPlanID != nil {
		t.Fatalf("equal change = %+v", same)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("an equal change was invoiced: %+v", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 1 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestTrialingChangesAtOnceAndBillsNothing(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	withPaymentMethod(e, c, "pm_card_visa")
	trial, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Trial", Currency: money.USD, UnitAmount: 5000, Interval: store.Monthly, TrialDays: 14}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: trial.ID, Quantity: 2})
	if err != nil || sub.Status != store.Trialing {
		t.Fatalf("subscription = %+v, %v", sub, err)
	}
	one := 1
	down, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &team.ID, Quantity: &one})
	if err != nil || down.PlanID != team.ID || down.Quantity != 1 || down.PendingPlanID != nil || down.Status != store.Trialing {
		t.Fatalf("trial downgrade = %+v, %v", down, err)
	}
	three := 3
	up, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &trial.ID, Quantity: &three})
	if err != nil || up.PlanID != trial.ID || up.Quantity != 3 || up.Status != store.Trialing {
		t.Fatalf("trial upgrade = %+v, %v", up, err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{}); len(invs) != 0 {
		t.Fatalf("a trial change was invoiced: %+v", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 0 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestIncompatiblePlansAreRefused(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	euro := e.CreatePlan(e.Acme, "Euro", "EUR", "20.00")
	yearly, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Yearly", Currency: money.USD, UnitAmount: 20000, Interval: store.Yearly}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	metered, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Calls", Currency: money.USD, UnitAmount: 2, Interval: store.Monthly, UsageType: store.Metered}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	for _, p := range []store.Plan{euro, yearly, metered} {
		if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &p.ID}); !errors.Is(err, subscriptions.ErrIncompatiblePlan) {
			t.Fatalf("change to %s: err = %v, want ErrIncompatiblePlan", p.Name, err)
		}
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, sub.ID); got.PlanID != team.ID {
		t.Fatalf("a refused change applied: %+v", got)
	}
}

