package api_test

import (
	"net/http"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

func TestSubscriptionPlanChangesOverTheAPI(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	euro := e.CreatePlan(e.Acme, "Euro", "EUR", "20.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c.ID, "plan_id": pro.ID, "quantity": 2}, &sub)

	// A downgrade is pending: the JSON shows it, and the plan does not change yet.
	m := e.MustDo(http.StatusOK, "PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"plan_id": team.ID, "quantity": 1}, &sub).Map(t)
	if sub.PlanID != pro.ID || sub.Quantity != 2 || sub.PendingPlanID == nil || *sub.PendingPlanID != team.ID || sub.PendingQuantity == nil || *sub.PendingQuantity != 1 {
		t.Fatalf("downgrade = %+v", sub)
	}
	if m["pending_plan_id"] != team.ID || m["pending_quantity"] != float64(1) {
		t.Fatalf("pending fields = %v", m)
	}

	// Changing back to the current plan and quantity clears it, and the JSON shows null.
	m = e.MustDo(http.StatusOK, "PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"plan_id": pro.ID, "quantity": 2}, &sub).Map(t)
	if _, ok := m["pending_plan_id"]; !ok || m["pending_plan_id"] != nil || m["pending_quantity"] != nil {
		t.Fatalf("pending fields after returning = %v", m)
	}

	// Plans in another currency cannot be changed between.
	if r := e.Do("PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"plan_id": euro.ID}); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "incompatible_plan" {
		t.Fatalf("change to another currency: %s", r)
	}
}

func TestUpgradeOverTheAPIAppliesAtOnce(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c.ID, "plan_id": team.ID}, &sub)
	e.Clock.Advance(10 * 24 * 60 * 60 * 1e9)
	e.MustDo(http.StatusOK, "PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"plan_id": pro.ID}, &sub)
	if sub.PlanID != pro.ID || sub.PendingPlanID != nil || sub.Status != store.Active {
		t.Fatalf("upgrade = %+v", sub)
	}
	var invs struct {
		Items []store.Invoice `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?subscription_id="+sub.ID, e.Acme.Key, nil, &invs)
	if len(invs.Items) != 2 || len(invs.Items[1].Lines) != 2 {
		t.Fatalf("invoices = %+v", invs.Items)
	}
}

